parameters.jsCode:
// US$ per 1 million tokens, by model. Add a row here when you switch EXTRACT_MODEL.
// This runs BEFORE any job is claimed or sent to Claude: a model without a price
// stops the run here, so no call is ever made whose cost we could not log.
const PRICES = {
  'claude-haiku-5-5': { input: 0.1, output: 0.5 },
};

const model = $env.EXTRACT_MODEL;
const price = PRICES[model];
if (!price) {
  throw new Error(`No price for model "${model}" (EXTRACT_MODEL). Add it to the table in "Look up model price". Nothing was sent to Claude.`);
}
return [{ json: { model, input_usd_per_mtok: price.input, output_usd_per_mtok: price.output } }];

